/* English overlay for the Agile track (ag001–ag100). Written in authored order (correct option first, same distractor order as the Italian source);
   enRotated() in content-en-rotate.js moves them to the order shown in Italian, so saved answer indexes mean the same in both languages.
   Terminology follows the CTFL-AT 2014 syllabus. Pending review by a CTFL-AT certified reviewer. */
(function(root){
'use strict';
const D=root.TrainerData;
const A='To answer, identify the purpose of the activity and check whether the proposal preserves collaboration, feedback and risk management. Judge the options in context, not by a single keyword.';
const B='In the clinic workshop, always separate the technical result from the patient’s need: quality requires both. Justify your choice before reading the options.';
// id: [prompt, options (correct first), reasons (aligned), explanation suffix]
const rows={
ag001:['An ambiguous requirement is blocking the team. Which choice reflects individuals and interactions?',['Talk it through directly and record the agreed examples','Add mandatory approvals without discussion','Get rid of every tool','Wait for the contract to settle the question'],['The conversation clarifies the meaning; recording the outcome keeps useful traceability.','Adding process without clarifying the need does not remove the ambiguity.','The Manifesto values people over tools, but it does not forbid tools.','Contract negotiation does not replace shared understanding.'],A],
ag002:['Feedback changes what the customer needs. How should the team respond?',['Assess value and impact, then adapt the plan','Ignore it because the plan has been approved','Implement it without analysing the risks','Abandon all planning'],['Adapting means deciding on new information while keeping control and objectives.','Following the plan at all costs throws away the value of feedback.','Welcoming change does not remove impact analysis.','Planning remains useful, but it evolves.'],A],
ag003:['Who is responsible for quality in a whole-team approach?',['The whole team, with complementary skills','The tester alone','Only whoever approves the release','An external group at the end of the project'],['Responsibility is shared; that does not make all skills interchangeable.','The tester contributes and facilitates, but does not take over everyone else’s responsibility.','Approving the release does not by itself produce quality.','Late checking does not replace prevention within the team.'],A],
ag004:['What is the main benefit of showing a prototype early?',['Checking assumptions about the need before investing heavily','Proving that the product has no defects','Removing acceptance testing','Freezing the requirements for good'],['Early feedback lets the team correct a wrong direction while it is still cheap.','A prototype does not prove that the final product is correct.','Feedback complements acceptance testing; it does not cancel it.','What the team learns may change the requirements.'],A],
ag005:['A story says “fast search”. What is the tester’s most useful contribution?',['Clarify load, threshold and expected results with the team','Accept “fast” as a measurable criterion','Choose the technical solution alone','Postpone every clarification to acceptance testing'],['Conditions and thresholds make the required quality observable and support verifiable examples.','“Fast” depends on expectations: without conditions it is not a reliable test oracle.','The need must be agreed first; imposing the implementation is not the first step.','Late clarification increases rework and disagreement.'],A],
ag006:['Which activity belongs mainly to iteration planning?',['Detailing the tests and tasks of the upcoming stories','Fixing all future releases once and for all','Delivering only a final report','Avoiding test estimates'],['Detail grows on imminent work, including risks, data and tests.','Release planning is broader and still adaptive, not fixed.','Final reporting is not iteration planning.','Test effort is part of the work to be estimated and planned.'],A],
ag007:['The “in progress” column exceeds its WIP limit. Which response helps the flow?',['Help finish the open work before starting anything new','Open more tasks to keep everyone busy','Hide the blocked tasks','Stop visualising the flow'],['Limiting work in progress reduces queues and makes bottlenecks visible.','More open tasks can increase waiting and multitasking.','Hiding a blockage prevents the team from dealing with it.','Visualisation is what helps the team spot the problem.'],A],
ag008:['In the 2020 Scrum Guide, does the Daily Scrum always require the three traditional questions?',['No: the format must support the inspection of progress toward the Sprint Goal','Yes: the three questions are mandatory','No: it is a presentation to the customer','Yes: it serves to approve each person’s tasks one by one'],['The three questions are one possible technique, not a requirement of the 2020 guide.','Mistaking a historical practice for an obligation leads to an overly absolute answer.','The Daily Scrum is not the Sprint Review with stakeholders.','The Daily Scrum serves to adapt the plan, not to control individuals.'],A],
ag009:['Which outcome makes a retrospective useful?',['A concrete improvement with an owner and a way to check it','A ranking of the people who made mistakes','Only a product demo','A promise never to have defects again'],['A verifiable action turns an observation into learning about the process.','Assigning blame reduces safety and collaboration.','The demo belongs to the product review; it does not replace the retrospective.','Zero future defects is not a realistic, verifiable promise.'],A],
ag010:['A CI pipeline is green. What can you conclude?',['The checks that ran passed under the pipeline’s conditions','The product has no defects','Every customer need is met','Future regressions are impossible'],['The result is limited to the checks, data, environment and version actually used.','Tests can miss defects and cover only part of the behaviour.','Technical correctness does not automatically prove usefulness to the customer.','Future changes can introduce new problems, which regression testing must look for.'],A],
ag011:['Manual regression testing grows with every iteration. Which strategy is sustainable?',['Automate stable, important checks and maintain the suite','Automate everything without weighing the costs','Give up regression testing','Keep even obsolete tests forever'],['Selection weighs risk, repeatability, cost and maintenance, and frees time for new investigation.','Flaky or low-value tests can cost more than they return.','New features can break existing ones.','Obsolete checks consume resources and can raise false alarms.'],A],
ag012:['What is one contribution of the tester in an Agile team?',['Helping the team prevent problems and communicate risks','Being solely responsible for all defects','Doing only the final acceptance check','Approving every business decision alone'],['Coaching, examples and critical thinking improve decisions throughout the lifecycle.','Responsibility for quality remains shared.','Getting involved early prevents problems instead of only detecting them.','Business decisions need the product owners.'],A],
ag013:['A burndown chart goes down steadily. Which conclusion is justified?',['The measured remaining work is decreasing, but quality needs other evidence','All requirements are correct','No product risks remain','Test coverage is complete'],['The chart shows remaining work; it is not proof of quality or coverage on its own.','Requirements can be wrong even when the tasks are complete.','Residual risk must be assessed with specific evidence.','A measure of effort does not measure coverage.'],A],
ag014:['What is the purpose of a build verification test?',['Quickly assess whether the build is fit for further testing','Replace all regression testing','Certify that there are no vulnerabilities','Measure user satisfaction'],['A short set of essential checks avoids investing in an unusable build.','A quick selection leaves out a lot of behaviour.','Security needs dedicated analysis and testing.','Basic functioning does not measure perceived value.'],A],
ag015:['How can a tester keep thinking critically while working closely with developers?',['Use cross-reviews and discuss assumptions and risks','Automatically accept every explanation of the code','Always keep the tester out of every conversation','Treat collaboration as incompatible with testing'],['Different perspectives can challenge assumptions without losing the shared context.','Agreement is not an independent check of the assumptions.','Isolation can lose information and delay feedback.','Collaboration and constructive criticism can strengthen each other.'],A],
ag016:['Which kind of documentation fits an Agile approach?',['Useful, up-to-date information proportionate to risks and constraints','No documents in any context','Every possible document before starting','Only code, even for regulatory decisions'],['Lightweight means useful and maintainable, not an absolute ban on documentation.','Traceability, maintenance and compliance needs exist.','Maximising documents is not the same as maximising value.','Code does not necessarily record the rationale or evidence required.'],A],
ag017:['What is the essential sequence of TDD?',['Failing test, minimal code to pass, refactoring','Complete code, release, first test','Refactoring without tests, then acceptance','Demo, contract, release'],['The expected failure validates the test; the code satisfies the behaviour, and refactoring improves the structure while the tests stay green.','The test comes too late to drive development.','There is no safety net of tests to protect the refactoring.','These may be project activities, but they are not the TDD cycle.'],A],
ag018:['Business, developer and tester define acceptance examples before the code. Which practice is this?',['ATDD','Load testing only','Debugging after release','Static analysis only'],['ATDD uses shared acceptance examples to guide the implementation.','Load testing is non-functional testing of one specific characteristic.','Debugging locates and fixes the causes of failures; it does not define acceptance before the code.','Static analysis does not describe collaboration on acceptance examples.'],A],
ag019:['What is the role of Given–When–Then in BDD scenarios?',['To express context, event and expected behaviour in a shared way','To prove every requirement automatically','To replace every conversation','To always identify component tests'],['The structure makes preconditions, action and result explicit; shared understanding stays central.','A textual format does not guarantee coverage or execution.','Scenarios come from conversations and support them.','The syntax does not determine the test level.'],A],
ag020:['Two features cost about the same: one handles payments, the other an icon colour. How should testing be prioritised?',['Assess the likelihood and impact of problems','Use alphabetical order only','Test only the easier one','Use incremental design as the risk measure'],['Risk analysis considers consequences and likelihood; in this context payments may well get priority.','Alphabetical order does not represent risk.','Ease says nothing about how serious a failure would be.','Incremental design is not a measure of likelihood and impact.'],A],
ag021:['What is a mind map used for in testing?',['Organising ideas, risks and exploration paths','Running UI tests automatically','Replacing version control','Proving that every risk is covered'],['A map helps explore and connect ideas; checking coverage needs further evidence.','Visualising ideas is not an execution engine.','Version control has a different purpose.','A map can be incomplete and does not prove that tests were run.'],A],
ag022:['Which set applies 2-value BVA to a valid integer field from 18 to 65 inclusive?',['17, 18, 65, 66','18, 40, 65','19, 20, 63, 64','40 only'],['Each boundary is checked with a valid value next to an invalid one: 17/18 and 65/66.','The middle value does not make up for the two missing outside values.','These values are inside the range and do not check the validity boundaries.','A single inside value is not boundary value analysis.'],A],
ag023:['Which statement about the testing quadrants is correct?',['They help reason about purposes and perspectives; they are not mandatory phases','Q1 must always finish before Q2','The quadrant makes risk analysis unnecessary','Q3 contains only component tests'],['The classification encourages a balanced strategy; activities from different quadrants can coexist.','It is not a sequential lifecycle.','Risk drives the choice and depth of the activities.','Q3 critiques the product from a business perspective, for example with exploratory testing and usability testing.'],A],
ag024:['Which is a good test charter for an exploratory testing session?',['Explore interrupted refunds to find inconsistent balances, recording evidence','Click around freely without recording results','Run only a fixed script','Guarantee that no defects exist'],['Mission and risk guide the learning; notes make results and gaps communicable.','Without a mission and a record it is hard to assess or report the session.','Exploratory testing adapts the tests to what you learn; it is not rigid execution.','No session can prove in general that there are no defects.'],A],
ag025:['Which choice is consistent with Agile values?',['Prefer direct discussion while keeping useful documentation','Ban documentation','Replace the customer with a contract','Prevent changes to the plan'],['Preferring interactions does not cancel the value of the other items.','A relative value is not a ban.','A contract does not replace discussion.','A plan can evolve when the information changes.'],B],
ag026:['In the clinic team, only the tester knows the double-booking cases. Which action improves the team’s collective work?',['Discuss these examples with development and the front office','Keep them until final acceptance testing','Delegate every quality decision to the tester','Remove the front office from the team'],['Sharing examples combines domain knowledge and technical skills before decisions are made.','Late checking misses chances to prevent problems.','Shared responsibility does not mean total delegation.','Without domain knowledge, the team may verify behaviour nobody can use.'],B],
ag027:['The booking demo reveals that choosing the clinic location is missing. Why was showing it early useful?',['The team can fix a misunderstood need before building on top of it','The demo certifies that there are no other defects','The demo makes later tests unnecessary','The feedback forces the team to throw away all the work'],['Early discovery reduces work based on a wrong assumption. It does not, however, guarantee a correct product.','A single observation does not cover the whole product.','The change will still have to be tested.','The change must be assessed: it does not imply a complete rewrite.'],B],
ag028:['While a story is being estimated, the tester points out that one edge case will need test data that is hard to prepare. Which advantage of the whole-team approach does this show?',['The risk enters the team’s estimate and planning straight away','The tester becomes solely responsible for the estimate','Developers no longer need to write unit tests','The story leaves the iteration without discussion'],['The tester’s skills enrich shared decisions: the cost of preparing the data is considered before committing.','The estimate stays a team decision; the tester contributes without replacing the others.','The tester’s input does not remove the tests developers write for their own code.','The issue must be discussed and assessed together, not used to drop the story by decree.']],
ag029:['Which practice supports the whole-team approach?',['Discussing every feature with business, development and testing together (power of three)','Physically separating testers to guarantee complete independence','Leaving requirements discussions to the product owner alone','Limiting the tester’s communication to formal defect reports'],['The three perspectives together clarify requirements and tests before work starts: the syllabus cites it as an example.','Separation reduces collaboration and feedback; in the whole-team approach the team works closely together.','The product owner plays a key role, but shared understanding also needs development and testing.','Formal-only communication slows feedback and undermines shared responsibility.']],
ag030:['At every iteration the customer sees working software. Which benefit is most relevant?',['Misunderstood requirements surface early, when fixing them costs less','The tests needed drop to zero','The customer can no longer change priorities','Requirements documentation becomes forbidden'],['Frequent feedback reveals misunderstood needs early, before other work builds on them.','Customer feedback does not replace tests: it complements them.','Feedback is exactly what allows the priority of work to change when needed.','Feedback does not remove useful documentation.']],
ag031:['In a project, quality problems only emerge in the last weeks before release. Which change makes best use of early feedback?',['Integrate and test in every iteration, showing the results to stakeholders','Postpone all testing to a longer final acceptance phase','Extend iterations to six months','Show the product only when it is defect-free'],['Frequent integration, testing and review produce feedback while it is still cheap to act.','A longer acceptance phase is still late: problems still surface at the end.','Longer iterations delay feedback instead of bringing it forward.','No product can be shown to be defect-free; waiting for that removes feedback.']],
ag032:['Which practice is characteristic of Extreme Programming (XP)?',['Pair programming','A Kanban board with WIP limits as the only tool','Phase gates with formal approval at the end of the project','Detailed, final planning of the whole project at the start'],['Pair programming is one of the XP practices, together with test-first and continuous integration.','WIP limits are typical of Kanban, not the distinctive practice of XP.','Phase gates belong to sequential models.','Planning everything up front, once and for all, conflicts with Agile adaptation.']],
ag033:['In Scrum, who manages and orders the product backlog?',['The product owner','The Scrum Master','The team’s tester','The development team, with nobody in charge'],['The product owner represents the customer and decides the order of the backlog.','The Scrum Master facilitates and removes impediments, but does not order the backlog.','The tester contributes risks and questions but does not own the backlog.','The team estimates and collaborates, but the backlog has an owner: the product owner.']],
ag034:['The story says: “As a customer I want to pay quickly”. Which rewrite is most testable?',['As a registered customer I want to pay with a saved card in no more than two steps, so I do not re-enter my details','Payment must be fast and intuitive','As the system I want to use the payments database','As a customer I want a better payment than the competitors offer'],['Role, action and benefit are clear, and “two steps with a saved card” can be checked with a concrete example.','“Fast” and “intuitive” have no threshold: no test can tell whether they are met.','It describes a technical choice, not a user’s need.','Comparing with competitors is not a criterion the team can verify.']],
ag035:['Story: “As a librarian I want to extend a loan”. Which acceptance criterion completes it in a testable way?',['A loan that is not overdue and has no reservations can be extended by 14 days, once; otherwise the system shows the reason for refusal','The extension must work correctly','The system must be easy for librarians to use','The extension must be implemented with a stored procedure'],['Conditions, duration, limit and behaviour on refusal let you derive positive and negative tests.','“Correctly” does not say what to check.','Ease of use without a measure cannot be verified.','It is an implementation constraint, not an acceptance criterion about behaviour.']],
ag036:['In refinement, a story is too big for one iteration and nobody agrees on what “reliable customer” means. Which action by the tester is most useful?',['Propose examples of reliable and unreliable customers, and suggest splitting the story into parts that can be tested separately','Accept the story and clarify the meaning during test execution','Write detailed test cases at once without involving the business','Ask for a complete requirements document before any discussion'],['Examples make the ambiguous term testable, and smaller stories can be completed and tested within one iteration.','Postponing the clarification moves the ambiguity to the most expensive moment.','Without the business, the test cases would embed an interpretation nobody agreed.','A complete document does not replace the conversation and delays feedback.']],
ag037:['In a retrospective, the tester proposes discussing the defects found late in the iteration. Why is this appropriate?',['Retrospectives cover process, people, relationships and tools, and can lead to testing improvements','It serves to find who is responsible for the defects','A retrospective replaces code review','It is not appropriate: testing is excluded from retrospectives'],['The syllabus lists process, people, organisations, relationships and tools among the topics, and expects test-related improvement decisions: late defects are a good starting point.','An effective retrospective avoids looking for someone to blame.','Code review is a different activity with its own purposes.','Testers take part and bring the quality perspective.']],
ag038:['Which condition makes a retrospective effective?',['A climate of trust in which problems can be raised without fear of blame','Using the minutes to assess individual performance','Holding it only at the end of the project','Discussing only successes'],['Without trust, real problems do not surface and improvement stays superficial.','Linking it to individual appraisals pushes people to hide problems.','The value comes from improving iteration after iteration, not from a final review.','Ignoring problems removes the very opportunities to improve.']],
ag039:['After a retrospective the team introduces a checklist for stories that are ready. What shows whether the improvement works?',['Checking in later iterations whether fewer stories are blocked by missing information','The checklist being approved unanimously','The number of items on the checklist','Nobody mentioning it any more'],['An improvement must be checked against its expected effect, with data from later iterations.','Initial agreement does not prove a result.','The length of the checklist does not measure its effect on the flow of work.','Silence may mean it was abandoned, not that it succeeded.']],
ag040:['Which risk remains even with well-configured continuous integration?',['Defects that no automated check covers can slip through','Changes are not integrated frequently','Feedback arrives only at the end of the release','The build is never compiled automatically'],['CI only gives feedback on what the automated checks cover: the rest needs other tests.','Frequent integration is exactly what CI provides.','CI gives feedback at every integration.','Automatic compilation is one of its basic activities.']],
ag041:['Which activity is typically part of a continuous integration process?',['At every integration: compile, run automated tests and static analysis, and notify the team of the result','Integrating code once a month after manual acceptance testing','Releasing every change to production with no checks','Replacing reviews with automated integration'],['Build, automated tests, static analysis and notification of the result are the typical activities described in the syllabus.','A monthly integration is not continuous and delays feedback.','CI integrates and verifies; releasing without checks is not part of it.','CI does not replace reviews: the two practices complement each other.']],
ag042:['Which tester activity belongs mainly to release planning?',['Helping define the test approach and the quality risks of the release','Breaking a story down into test tasks for the iteration','Running regression testing on today’s build','Fixing the faulty code'],['In release planning the tester helps assess risks, approach and effort at release level.','Detailed tasks belong to iteration planning.','That is test execution, not planning.','Fixing is debugging, a development task.']],
ag043:['Which difference between release planning and iteration planning is correct?',['Release planning looks at the release as a whole; iteration planning selects and details the stories of a single iteration','Iteration planning looks at the whole release; release planning at a single iteration','They are the same activity with different names','Release planning is repeated every day'],['Release planning defines the backlog and objectives of the release; iteration planning chooses and breaks down the work of the iteration.','The order is reversed.','The two activities differ in horizon and level of detail.','Daily realignment happens in the stand-up, not in release planning.']],
ag044:['When is a build verification test typically run?',['Right after a new build is deployed to the test environment','Only at the end of the release, before delivery','Before the user stories are written','Once a year, during the audit'],['The build verification test covers critical functions and integration points as soon as the build arrives, so the team does not waste time on an unstable build.','Running it only at the end would defeat its purpose: immediate feedback on every build.','Without a build there is nothing to verify.','A yearly check gives no feedback on the builds of the iteration.']],
ag045:['What is a configuration item?',['An item identified and managed under configuration management, such as versioned code, tests or test data','A production setting anyone can change freely','A defect logged in the tracking system','A user story that has been completed'],['Code, automated tests, manual test cases and test data can be configuration items: versioned and tracked over time.','An item under configuration management is controlled precisely, not freely changeable.','A defect is something else, although the defect report can be stored and linked to items.','The status of a story does not make it a configuration item.']],
ag046:['What is the purpose of configuration management?',['Identifying items and controlling their versions and changes, while keeping their history','Planning the iterations of the release','Measuring the team’s velocity','Formally approving the requirements'],['With configuration management, tests and results stay aligned with the builds: you know what was tested on which version.','Planning iterations is a different activity.','Velocity is a progress metric, not the purpose of configuration management.','Approving requirements is not its goal.']],
ag047:['Which difference between a sequential model and an Agile project concerns when testing happens?',['In an Agile project testing takes place throughout the iteration, not as a final activity','In an Agile project testing starts only after the last iteration','Sequential models have no test levels','In an Agile project business stakeholders do not test'],['Iterations are short, and development, integration and testing happen in parallel and overlap.','It is the opposite: testing left to the end is typical of sequential models.','Test levels exist in both models.','In Agile projects business stakeholders also try out the stories during implementation.']],
ag048:['Compared with a sequential model, what happens to test levels in many Agile projects?',['They overlap, because requirements, design and code can change during the iteration','Each must be formally closed before the next one starts','Exit criteria are abolished','Only one level remains: acceptance testing'],['In sequential models the exit from one level is often the entry to the next; in Agile projects levels tend to overlap.','This is the typical rule of sequential models, which often does not apply in Agile projects.','Criteria such as the definition of done still exist.','Unit testing, feature testing, regression testing and other levels are still there.']],
ag049:['During an iteration, which sequence of test activities does a user story typically go through?',['Developer unit testing, then feature verification against the acceptance criteria and feature validation with stakeholders','First user acceptance testing, then unit testing','A single round of system testing at the end of the release','Feature validation before writing the code'],['The story moves from unit testing to verification against the acceptance criteria, often automated, and to collaborative validation of its usefulness.','The sequence is reversed: unit tests go along with development.','Leaving everything to the end contradicts the integration of development and testing.','Without a feature there is nothing to validate.']],
ag050:['A tester pairs with a developer on the same feature. Which benefit is most likely?',['Development and testing of the feature move forward together, with immediate feedback','The tester no longer needs to design tests','The developer stops writing unit tests','Independence of testing is maximised'],['Pairing, cited by the syllabus, integrates development and testing: problems surface while the feature takes shape.','Test design is still needed.','Unit tests remain the developer’s job.','Working closely together reduces independence rather than maximising it.']],
ag051:['According to the good practice cited by the syllabus, when is a feature “done”?',['When it has been integrated and tested with the system','When the code compiles','When the developer’s unit tests pass','When the story has been estimated'],['A feature is not considered complete until it has been integrated and tested with the system.','Compiling says nothing about behaviour.','Unit tests alone do not check integration or the acceptance criteria.','Estimation comes before the work.']],
ag052:['A tester embedded long-term in the Agile team works with the developers every day. Which risk must be managed?',['Loss of independence and objective evaluation','Being unable to automate the tests','Lack of quick feedback','Poor knowledge of the product'],['Being in the team brings knowledge and speed, but can reduce detachment and objectivity.','Being embedded does not prevent test automation.','Closeness to the team speeds up feedback.','Working in the team, the tester gets to know the product well.']],
ag053:['A separate test team is assigned only in the last days of each sprint. Which problem is typical?',['Time pressure and little understanding of the new features','Total loss of independence','Being too close to the developers','Being unable to run manual tests'],['Independence is preserved, but arriving late brings pressure, little knowledge of what is new and difficult relationships.','The separation is precisely what preserves independence.','The problem is distance, not closeness.','Manual tests are still possible.']],
ag054:['Which organisation combines independence with good knowledge of the product?',['An independent test team whose testers are assigned to Agile teams long-term, from the start','Testers assigned on demand in the last days of the sprint','Only automated tests written by developers','No testers: the product owner checks everything'],['A stable assignment lets testers learn the product and build relationships while still belonging to an independent team.','Arriving at the end of the sprint means little knowledge and a lot of pressure.','Testing done only by developers reduces independence.','The product owner does not replace structured testing.']],
ag055:['Which tool gives an immediate, detailed view of the whole team’s status, testing included?',['The task board with columns such as “to do”, “in progress”, “verify” and “done”','The test plan approved at the start of the project','The attendance register','The contract with the customer'],['Stories, development tasks and test tasks move across the board: everyone can see the status at any time.','An initial plan does not show the current status.','Attendance says nothing about progress.','The contract does not describe how the work is progressing.']],
ag056:['How should test metrics be used in an Agile team?',['To support decisions and improvement, not to reward or punish individuals','To rank team members','To replace the conversations in the stand-up','Only at the end of the project, in a final report'],['The syllabus asks for relevant metrics that help decisions and are never used to reward, punish or isolate anyone.','Ranking people is exactly the use to avoid.','Metrics complement communication; they do not replace it.','An Agile project needs up-to-date information during the iterations.']],
ag057:['A test task has not moved on the board for three days. What is the response most consistent with the syllabus?',['Raise it in the stand-up so the team can analyse and remove the blocker','Wait for the retrospective at the end of the iteration','Move it to “done” so it does not slow the burndown','Solve it alone without telling anyone'],['Blockers, testing ones included, are raised in the daily stand-up so the team can act at once.','Waiting for the retrospective leaves the blocker in place for days.','Faking the status makes the board useless.','The problem affects the team and its ability to complete the iteration.']],
ag058:['The product grows with every iteration and there is not enough time to re-run every test. What does the syllabus recommend?',['Review the tests, select candidates for regression testing, automate as many as possible and retire those no longer relevant','Run only the tests of the current iteration','Freeze the regression suite at the first release','Give up regression testing and rely on the customer'],['The suite must be curated at every iteration: selection, test automation and retirement of tests keep regression risk under control.','Changes can break features from earlier iterations.','A frozen suite ages as the features change.','The regression risk would be left uncovered.']],
ag059:['An automated regression test fails after a behaviour change that was intended and agreed with the business. What should be done?',['Update the test, and the story if needed, to the new acceptance criteria','Disable the whole regression testing suite','Open a defect of maximum severity without analysis','Ignore the failure until it passes by itself'],['The team analyses the failure: if it comes from a legitimate change, the test is updated or retired.','Disabling the suite removes the protection against regression.','Before calling it a defect, you need to understand the cause.','A failing test that is ignored stops informing anyone.']],
ag060:['Beyond Foundation skills, which skills does the syllabus expect from an Agile tester?',['Test automation, TDD, ATDD and black-box, white-box and experience-based techniques','Managing the company budget','Administering supplier contracts','Graphic design of the user interface'],['The syllabus lists precisely test automation, TDD, ATDD and black-box, white-box and experience-based techniques.','The budget is not a skill required of the tester.','Contract management is outside the role.','Graphic design is not among the expected skills.']],
ag061:['Which behaviour reflects the interpersonal skills expected of an Agile tester?',['Actively gathering information from stakeholders rather than relying only on written specifications','Waiting for complete specifications before asking questions','Avoiding discussion so as not to slow the team down','Communicating only through defect reports'],['The Agile tester actively seeks information from people.','Waiting for complete specifications slows feedback and leaves ambiguity.','Constructive discussion is part of the role.','Formal-only communication limits collaboration.']],
ag062:['A tester is positive and solution-oriented with the team, but challenges a risky solution. Which skills does this show?',['Solution orientation together with critical, sceptical thinking about the product','Absolute independence and refusal to collaborate','Accepting every decision to keep the peace','Domain knowledge in place of testing skills'],['The syllabus asks for a positive attitude together with a critical, quality-oriented view.','Challenging a choice does not mean refusing to collaborate.','Accepting everything to keep the peace is a risk, not a skill.','The situation is not about domain knowledge.']],
ag063:['Which activity is part of the tester’s role in an Agile team?',['Measuring and reporting test coverage across all relevant coverage dimensions','Deciding the order of the product backlog alone','Approving the release budget','Replacing the Scrum Master'],['Measuring coverage is among the activities the syllabus assigns to the tester.','The order of the backlog belongs to the product owner.','The budget is not a tester’s task.','The roles remain distinct.']],
ag064:['The team consistently neglects non-functional testing. Which action is part of the tester’s role?',['Coach the team on those aspects of testing and make sure the tasks are planned','Run all the non-functional tests alone, without saying so','Stay quiet to avoid tension','Block the release without discussing it'],['Coaching on testing and planning the test tasks in the iterations are activities expected of the tester.','Working alone and in silence takes visibility away from the team.','Staying silent about ineffective practices is an organisational risk cited by the syllabus.','Release decisions are taken together, based on information.']],
ag065:['Which organisational risk for Agile testers does the syllabus mention?',['Becoming tolerant of, or silent about, inefficient or low-quality practices','Having too much free time in the iterations','Not being able to attend retrospectives','Having to work only with manual tests'],['The syllabus also mentions losing the tester mindset and struggling to keep pace with change.','The problem cited is the opposite: keeping pace with change.','Testers take part in retrospectives.','Test automation is widespread in Agile projects.']],
ag066:['What is a unit test framework?',['A tool that supports writing and automatically running unit tests','The document describing the test strategy of the release','The set of acceptance criteria of a story','A consensus-based estimation technique'],['The framework provides structure, assertions and automatic execution of unit tests, such as those written in TDD.','The test strategy is a document, not an execution tool.','Acceptance criteria are conditions, not a tool.','The consensus-based estimation technique is planning poker.']],
ag067:['What is a test charter?',['A document stating the objective and test conditions of a time-boxed exploratory testing session','The contract signed with the customer','The final test completion report','The list of open defects'],['The charter guides the exploratory testing session: what to explore, for what purpose and within what time.','The contract does not guide a test session.','The report summarises results; it does not guide a session.','The list of defects is useful information, not a charter.']],
ag068:['What is a quality risk (product risk)?',['A potential problem whose main effect is on the quality of the product','The test environment being delivered late','An item under configuration management','An effort estimate in story points'],['When the main effect concerns product quality, it is called a quality risk or product risk.','A late environment threatens the project: it is a project risk.','A configuration item is not a risk.','An estimate is not a risk.']],
ag069:['What does the test pyramid represent?',['Many tests at the lower levels, such as unit and integration, and progressively fewer towards the higher levels','Many acceptance tests and few unit tests','The same number of tests at every level','The hierarchy of roles in the team'],['The wide base means many unit and integration tests; the number decreases towards system and acceptance.','This inverted shape, heavy on acceptance testing and often called the “ice-cream cone”, is what the pyramid aims to avoid.','The pyramid indicates exactly an uneven distribution.','It is about test levels, not how people are organised.']],
ag070:['According to the syllabus, which tools are usually used to automate the tests at the base of the pyramid?',['API-based tools','GUI-based tools','None: the base is tested only manually','Contract management tools'],['Unit and integration tests are usually automated with API-based tools.','GUI-based tools are typical of the system and acceptance levels.','The base of the pyramid is precisely the most automated part.','These are not test tools.']],
ag071:['Which principle is the test pyramid based on?',['Early QA and testing, to remove defects as early as possible','Exhaustive testing is possible at the lower levels','Acceptance testing is cheaper to maintain','Test automation eliminates every manual test'],['The syllabus links the pyramid to the principle of early testing: removing defects early in the lifecycle.','Exhaustive testing remains impossible at every level.','Higher-level tests are usually slower and more expensive to maintain.','The pyramid does not eliminate manual tests.']],
ag072:['A team runs load and security tests. Which quadrant do they belong to?',['Q4: technology-facing, critiquing the product','Q1: unit tests supporting the developers','Q2: business-facing functional tests','Q3: exploratory testing and usability tests'],['Performance, load, stress, security and technical reliability tests are Q4 tests, often automated.','Q1 contains unit tests.','Q2 confirms behaviour against the acceptance criteria.','Q3 critiques the product from the user’s point of view.']],
ag073:['Which description matches quadrant Q2?',['System level, business-facing, confirming product behaviour with functional tests, examples and story tests','Unit level, technology-facing, supporting the developers','Critiquing the product with performance and security tests','Containing user acceptance tests, alpha and beta tests'],['Q2 checks the acceptance criteria, manually or automatically, and is useful for building automated regression testing.','This is the description of Q1.','This is the description of Q4.','These tests belong to Q3.']],
ag074:['A tester plans exploratory testing and usability tests with real users. What does the quadrant model say?',['They are in Q3: business-facing, critiquing the product and often manual','They are in Q1 and must be added to CI as unit tests','They are outside the quadrants because they are manual','They are static tests and stay outside the model'],['Q3 includes exploratory, usability, scenario and user acceptance tests, with realistic scenarios and data.','Q1 is about the developers’ unit tests.','The quadrants include both manual and automated tests.','The quadrants apply to dynamic testing, and these tests are dynamic.']],
ag075:['Sprint zero of a new Scrum project: how does the tester contribute?',['With the initial test strategy, a first quality risk analysis, test metrics and the definition of done','With full regression testing and the release report','By writing the code of the first stories','With final acceptance testing together with the customer'],['In sprint zero the team prepares the strategy, risks, metrics, tools, task board and definition of done.','There is no product yet to run regression tests on.','Stories are not developed yet in sprint zero.','Final acceptance comes much later.']],
ag076:['In sprint planning the task “Test the payments module” appears, estimated at 6 days. What does the tester propose?',['Breaking it into tasks of one or two days, linked to the acceptance criteria and visible on the task board','Accepting it as it is and updating it at the end of the sprint','Removing it from the board so it does not slow the burndown','Asking the product owner to do it'],['The syllabus recommends tasks of one or two days: progress and blockers become visible every day.','A six-day task hides delays until the end.','Hiding the test work misrepresents the team’s status.','Testing remains a team task and is not delegated to the product owner.']],
ag077:['Stakeholders do not trust the Scrum team’s test results. Which practice best addresses the problem?',['Making the test strategy credible by informing stakeholders about the test process','Reducing the number of tests run','No longer showing the task board','Handing all testing to an external team at the end of the project'],['Among good practices for Scrum teams the syllabus cites credibility: without information about the process, the results do not convince.','Fewer tests do not increase trust.','Less transparency makes trust worse.','Late, external testing brings the time and knowledge problems seen earlier.']],
ag078:['Iteration planning has three items: A) interest calculation for a mortgage, used by every customer; B) a new button colour; C) a monthly report, already stable, used by two people. Which choice is most justified?',['A first and with the most testing; B and C later, with less testing','B first because it is the quickest','The same depth of testing for all','C first because it is already stable'],['A combines high impact (every customer, money) with significant likelihood: it should start first and get the most testing.','Speed is not a measure of risk.','The depth of testing must be proportional to the level of risk.','C’s stability lowers the likelihood of defects: if anything, it comes later.']],
ag079:['For the story “product search” the team identifies the risk “slow responses with many users”. How is it classified and what mitigates it best?',['A non-functional efficiency risk: performance tests with realistic loads','A functional accuracy risk: a decision table','A project risk: revise the plan','A usability risk: exploratory testing of the interface'],['Slowness is a quality risk tied to efficiency and response time: it should be mitigated with non-functional testing, specifically performance testing.','The risk is not about calculations or rules.','The problem affects the product, not the plan.','Usability is about understandability, not response times under load.']],
ag080:['While identifying risks, the team finds that many stories have vague acceptance criteria. Which mitigation is possible even before running any test?',['Reviewing the stories thoroughly with the business to clarify the criteria','Making the sprint longer','Ignoring the problem and testing what can be tested','Postponing the risk analysis to the next release'],['The syllabus notes that some risks can be mitigated before test execution, for example by a thorough review of the stories.','More time does not clarify the criteria.','Tests based on vague criteria leave the risk uncovered.','Postponing leaves the risk active exactly when it matters.']],
ag081:['In planning poker the cards revealed are 3, 5, 5 and 21. What does the team do?',['Discuss the differences, starting with whoever chose 3 and 21, and estimate again','Use the average, 8.5','Choose 21, the most cautious value, without discussion','Discard the 21 and assign 5'],['Diverging estimates are discussed, because they reveal different knowledge or assumptions; then the round is repeated.','The average is not in the sequence and skips the discussion that gives the technique its value.','Rules such as taking the highest value serve to limit the number of rounds, not to avoid discussion.','Discarding the outlier loses the information it carries.']],
ag082:['Two stories need the same development effort: one is about calculating commissions (high risk), the other an information text (low risk). How is testing reflected in the estimate?',['The high-risk story gets a higher estimate, because it needs deeper testing','The same estimate, because development is the same','The low-risk story gets the higher estimate','Testing is not part of the estimate and is estimated at the end of the release'],['The estimate also covers testing: higher risk needs more thorough tests, and therefore more effort.','Ignoring testing underestimates the risky story.','Low risk needs less testing, not more.','In Agile projects the estimate includes the test effort.']],
ag083:['All the estimators show very high values, 55 and 89, for a story. What does this usually indicate?',['The story is not well understood or should be split into smaller stories','The story is the most important in the backlog','The team is not very productive','The story needs no testing'],['The syllabus explains that a high estimate usually signals poor understanding or a story that is too big.','Size and priority are different things.','A high estimate says something about the story, not about productivity.','The size of the estimate does not remove testing.']],
ag084:['The integration definition of done requires all interfaces between units to be tested. The report: 9 of 10 interfaces tested, no major defects open. What do you conclude?',['Integration is not “done” yet: one interface is missing','It is “done”, because there are no major defects','It is “done”, because 90% is enough','The definition of done does not apply to integration'],['Every criterion must be met: having no major defects does not make up for the untested interface.','Meeting one criterion does not replace the others.','The criterion asks for all interfaces, not a threshold.','Each test level has its own definition of done.']],
ag085:['The checkout story says nothing about response times, but the user profiles show access peaks during the sales. How do you use this information?',['As an additional test basis: propose a criterion and performance tests for the peaks','You ignore it, because only the story counts','You use it only after the release','You log it as a defect'],['User profiles are among the test bases cited by the syllabus: they point to a risk to discuss and cover.','The story is an important test basis, but not the only one.','Discovering the problem in production costs more.','No failure has been observed: it is information for testing.']],
ag086:['At the end of the iteration every story has been tested individually, but the integration of the features has not been tested and two non-critical defects are not in the backlog. According to the iteration definition of done in the syllabus, what is missing?',['Testing the integration of the features and adding the non-critical defects to the backlog with a priority','Nothing: the iteration is complete','Only fixing all the non-critical defects immediately','Only writing the documentation'],['The iteration definition of done requires tested integration, and non-critical defects that cannot be fixed within the iteration added to the backlog with a priority.','Two elements of the definition of done are not met.','Non-critical defects may remain, as long as they are tracked and prioritised.','Documentation does not fix the two gaps.']],
ag087:['A product owner asks how to make acceptance criteria testable. Which advice is correct?',['Describe observable behaviour, business rules, data and measurable quality characteristics','Use adjectives such as “fast” and “simple”','Leave the details to the developers','Write only the title of the story'],['The syllabus lists behaviour, quality, scenarios, rules, interfaces, constraints and data among the aspects to cover.','Adjectives without a measure cannot be verified.','Without shared criteria everyone interprets them differently.','The title is not enough to know when the story is satisfied.']],
ag088:['Which acceptance criterion is a data definition?',['The postcode has 5 digits, is mandatory and has no default value','The page loads in under 2 seconds','Only customers with an active contract can request a refund','The system sends the order to the warehouse through an API'],['The format, type, allowed values and default values of a data item are data definitions.','It is a quality characteristic (performance).','It is a business rule.','It is an external interface.']],
ag089:['How do you explain to the business that “the system must be reliable” is not a testable criterion?',['By proposing a measurable criterion, for example a maximum number of errors allowed over a given number of operations','By proposing to drop the requirement','By leaving the judgement to the tester','By postponing the topic until after the release'],['A measurable threshold makes a quality characteristic verifiable, as the syllabus suggests for reliability.','The need for reliability is still real.','Without a shared criterion the judgement becomes subjective.','Postponing increases risk and cost.']],
ag090:['Story: “As a customer I want to use a valid discount code to get 10% off the total”. With ATDD, which example do you write first?',['Given a €50 cart and the valid code SAVE10, when I apply it, then the total is €45','Given an expired code, when I apply it, then an error message appears','The cart page handles 1,000 concurrent users','The discount also applies to shipping costs'],['In ATDD you start with the positive examples, the path where everything goes as expected; negative and non-functional cases follow.','It is a good example, but negative: it comes after the positive ones.','Non-functional testing comes after the positive path.','Shipping is not in the story: an example must not add anything to the story.']],
ag091:['In the specification workshop the example “the discount code also works on products already on sale” comes up, but the story does not cover it. How do you proceed?',['Clarify with the business and update the story before turning it into a test','Add it as a test without changing the story','Discard it without discussion','Let the developer decide'],['Examples must not describe aspects missing from the story: the gap is resolved in the story, with the business.','A test that goes beyond the story creates hidden requirements.','The case is real: ignoring it leaves the ambiguity in place.','The decision belongs to the business, not only to development.']],
ag092:['Two ATDD examples both check the 10% discount with a valid code, on €50 and €60 carts, with no other difference. What should be done?',['Replace one of them with a different case, for example an expired code, because two examples must not describe the same characteristic','Keep both: more identical examples increase coverage','Turn them into unit tests','Delete both'],['According to the syllabus no two examples should describe the same characteristic: better to use the example for a case not yet covered.','Equivalent examples add no coverage.','The problem is redundancy, not the test level.','The positive case is needed: one of the two must stay.']],
ag093:['Story: “A customer can order from 1 to 10 tickets per event”. With 2-value BVA, which quantities do you choose?',['0, 1, 10 and 11','1, 5 and 10','0 and 10','2 and 9'],['For each boundary you need the boundary value and its neighbour in the adjacent partition: 0/1 and 10/11.','5 is not a boundary value, and the invalid values are missing.','The valid boundary 1 and the invalid value 11 are missing.','2 and 9 are inside neighbours, not the boundaries with the invalid partitions.']],
ag094:['Story: “Shipping is free for orders of €50 or more and for Premium customers at any amount”. With a full decision table, how many rules are there and which case pays for shipping?',['4 rules; only a non-Premium customer with an order under €50 pays','2 rules; every order under €50 pays','4 rules; Premium customers under €50 pay','3 rules; orders of €50 or more pay'],['Two Boolean conditions give 4 combinations; only “not Premium and under €50” meets neither.','Two rules do not cover all combinations, and Premium customers under €50 do not pay.','Premium customers get free shipping at any amount.','The full table has 4 rules, and orders over €50 do not pay.']],
ag095:['Story: “Search responds within 2 seconds with up to 200 concurrent users”. Which tests do you derive by applying BVA to the load?',['Measure response times with 200 and with 201 concurrent users','Measure with 1 user only','Measure with 100 users, the middle of the range','Only check that search returns results'],['Black-box techniques also apply to non-functional testing: 200 is the boundary, 201 the first value beyond it.','One user does not exercise the boundary.','The middle value does not check the boundary.','That is functional testing only: it ignores the performance requirement.']],
ag096:['A test charter says: “Actor: registered customer. Purpose: check editing of addresses. Setup: account with two addresses. Activities: create, read, update, delete addresses”. Which element is missing to decide whether the observed behaviour is correct?',['The oracle notes','The developer’s name','The project budget','The release date'],['Oracle notes say how to evaluate the results, for example which reference to compare them with: they act as the test oracle of the session.','It is not an element of a charter.','It does not help evaluate the behaviour.','It does not say how to judge the results.']],
ag097:['In an exploratory testing session on the booking app you apply the “interruptions” heuristic. Which test follows it?',['Closing the app during payment and reopening it to check the status of the booking','Trying a booking with 0 and with 1 seat','Creating, reading, updating and deleting a booking','Changing the device language'],['Log-offs, shutdowns or restarts in the middle of an operation are the interruptions heuristic.','This is the boundaries heuristic.','This is the CRUD heuristic.','This is the configuration variations heuristic.']],
ag098:['A newly delivered function is not yet known to anyone in the team. Which exploratory testing session should be planned first?',['A survey session, to learn how it works','A deep coverage session on corner cases','An automated regression testing session','None: detailed scripts are needed first'],['In session-based test management you start with a survey to learn the function, then analysis and deep coverage.','Without knowing the function it is hard to pick the right corner cases.','Automated regression testing is not an exploratory testing session.','Exploratory testing is useful precisely when details are scarce.']],
ag099:['Which tool do Agile teams often adopt instead of separate tools for tests, requirements and defects?',['An application lifecycle management or task management tool, with task board, burndown and user stories','A spreadsheet for holidays','A compiler','An antivirus'],['The syllabus mentions all-inclusive tools with the features typical of Agile development.','It does not manage the team’s work.','It is a development tool, not a management tool.','It has nothing to do with managing tasks.']],
ag100:['Why are configuration management tools important for Agile testers?',['To store and manage the many automated tests at all levels and their artefacts','To estimate stories in planning poker','To replace the task board','To write the acceptance criteria'],['The large number of automated tests makes it essential to version and manage them together with the builds.','Estimation is a different activity.','The task board has a different purpose.','Acceptance criteria are defined with the business.']]
};
root.TestPilotEnAuthored=Object.assign(root.TestPilotEnAuthored||{},rows);
})(typeof globalThis!=='undefined'?globalThis:this);
